+                    } else {
+                        LOG.info(
+                                "Excluding {}{}, not configured in reporter list ({}).",
+                                reporterSetupInfo.reporterPrefix.replace('.', ' '),
+                                reporterName,
+                                includedReportersString);
+                    }
+                }
+            }
+        }
+        return namedOrderedReporters;
