+    private StreamPhysicalRel visitSink(
+            final StreamPhysicalSink sink, final ImmutableBitSet requireDeterminism) {
+        if (inputInsertOnly(sink)) {
+            // for append stream, not care about NDU
+            return transmitDeterminismRequirement(sink, NO_REQUIRED_DETERMINISM);
+        } else {
+            // for update streaming, when
